//! Explicit mutating generation transport over the resident compiler host.
use crate::{request::{BuildRequest,BuildCommand},generation_transaction::{Report,State}};
use serde::{Serialize,Deserialize,ser::{SerializeSeq,SerializeStruct}};
use std::{error::Error,fmt,fs::File,io::{self,Read,Write,Seek,SeekFrom},path::Path};
pub(crate) const FRAGMENT:usize=65_536;pub const MAX_REPORT_BYTES:usize=64*1024*1024;const OUTPUT:u64=MAX_REPORT_BYTES as u64;
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub(crate) struct GenerationRequest{pub build:BuildRequest,pub check:bool}
impl GenerationRequest{pub(super) fn validate(&self)->io::Result<()>{let build=&self.build;if build.command!=BuildCommand::PrepareQuery||build.diagnostic_declarations||build.source_questions.is_some()||build.no_daemon||build.replay_inputs.is_some()||build.artifact_directory.is_some(){return Err(io::Error::new(io::ErrorKind::InvalidInput,"native generation requires strict retained PrepareQuery without replay or executable publication"))}let policy=build.policy_inputs.as_ref().ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"generation needs actual workspace intent"))?;let workspace=policy.workspace.as_ref().ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"generation needs actual workspace scope"))?;if policy.workspace_generators.is_empty()||policy.workspace_generators.len()>crate::GeneratorName::REGISTERED_COUNT{return Err(io::Error::new(io::ErrorKind::InvalidInput,"generation requires admitted generator names"))}let cache=build.cache_root.as_ref().filter(|path|path.is_absolute()).ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"generation requires explicit absolute existing cache_root"))?;if !workspace.root.is_absolute(){return Err(io::Error::new(io::ErrorKind::InvalidInput,"generation workspace root must be absolute"))}Ok(())}}
#[derive(Clone,Copy,Debug,Eq,PartialEq,Serialize,Deserialize)]#[serde(rename_all="snake_case")]pub(crate) enum Status{Completed,Failed}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub(crate) struct GenerationTerminal{pub status:Status,pub clean:bool,pub fragments:u32,pub total:u64,pub hash:u128,pub committed:bool,pub may_have_changed:bool,pub cleanup_warnings:u32}
pub(super) fn validate_cache(build:&BuildRequest)->io::Result<()>{let root=&build.policy_inputs.as_ref().and_then(|policy|policy.workspace.as_ref()).ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"generation workspace unavailable"))?.root;let cache=build.cache_root.as_ref().ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"generation cache unavailable"))?;let root=std::fs::canonicalize(root)?;let cache=std::fs::canonicalize(cache)?;if !cache.is_dir()||cache.starts_with(root){return Err(io::Error::new(io::ErrorKind::InvalidInput,"generation cache must be an existing directory outside workspace"))}Ok(())}
struct DisplayValue<'a,T:?Sized>(&'a T);impl<T:fmt::Display+?Sized>Serialize for DisplayValue<'_,T>{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{s.collect_str(self.0)}}
struct IoKind(io::ErrorKind);impl fmt::Display for IoKind{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{:?}",self.0)}}
fn actual_io<'a>(mut error:&'a(dyn Error+'static))->Option<&'a io::Error>{loop{if let Some(io)=error.downcast_ref::<io::Error>(){return Some(io)}error=error.source()?;}}
struct Failure<'a>(&'a(dyn Error+'static));impl Serialize for Failure<'_>{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut row=s.serialize_struct("Failure",4)?;row.serialize_field("kind",&crate::request_failure::classify(self.0))?;row.serialize_field("message",&DisplayValue(self.0))?;let io=actual_io(self.0);row.serialize_field("os_code",&io.and_then(io::Error::raw_os_error))?;row.serialize_field("io_kind",&io.map(|error|DisplayValueKind(error.kind())))?;row.end()}}
struct DisplayValueKind(io::ErrorKind);impl Serialize for DisplayValueKind{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{s.collect_str(&IoKind(self.0))}}
struct Rows<'a>(&'a[crate::generation_transaction::OutputRow]);impl Serialize for Rows<'_>{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut rows=s.serialize_seq(Some(self.0.len()))?;#[derive(Serialize)]struct Row<'a>{generator:&'static str,path:&'a Path,state:&'static str}for row in self.0{rows.serialize_element(&Row{generator:row.name.name(),path:&row.path,state:match row.state{State::Fresh=>"fresh",State::Written=>"written",State::Stale=>"stale",State::NotIncluded=>"not_included"}})?;}rows.end()}}
struct Diagnostics<'a>(&'a[crate::generation_transaction::Diagnostic]);impl Serialize for Diagnostics<'_>{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut rows=s.serialize_seq(Some(self.0.len()))?;#[derive(Serialize)]struct Row<'a>{generator:&'static str,relative:&'a str,line:u32,message:&'a str}for row in self.0{rows.serialize_element(&Row{generator:row.name.name(),relative:&row.relative,line:row.line,message:&row.message})?;}rows.end()}}
struct Warnings<'a>(&'a[crate::generation_transaction::RollbackFailure],&'a[crate::generation_transaction::RollbackFailure]);impl Serialize for Warnings<'_>{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut rows=s.serialize_seq(Some(self.0.len()+self.1.len()))?;#[derive(Serialize)]struct Row<'a>{path:&'a Path,failure:Failure<'a>}for row in self.0.iter().chain(self.1){rows.serialize_element(&Row{path:&row.path,failure:Failure(&row.error)})?;}rows.end()}}
struct ReportWire<'a>(&'a Report,bool);impl Serialize for ReportWire<'_>{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let report=self.0;let mut s=s.serialize_struct("GenerationReport",7)?;s.serialize_field("schema","native-generation-v1")?;s.serialize_field("clean",&self.1)?;s.serialize_field("rows",&Rows(&report.rows))?;s.serialize_field("diagnostics",&Diagnostics(&report.diagnostics))?;s.serialize_field("changed",&report.changed)?;s.serialize_field("cleanup",&Warnings(&report.cleanup,&[]))?;s.serialize_field("committed",&report.committed)?;s.end()}}
struct FailureWire<'a>{primary:&'a(dyn Error+'static),rollback:&'a[crate::generation_transaction::RollbackFailure],cleanup:&'a[crate::generation_transaction::RollbackFailure],pending_cleanup:&'a[crate::generation_transaction::RollbackFailure],committed:bool}
impl Serialize for FailureWire<'_>{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut s=s.serialize_struct("GenerationFailure",5)?;s.serialize_field("schema","native-generation-failure-v1")?;s.serialize_field("primary",&Failure(self.primary))?;s.serialize_field("rollback",&Warnings(self.rollback,&[]))?;s.serialize_field("cleanup",&Warnings(self.cleanup,self.pending_cleanup))?;s.serialize_field("committed",&self.committed)?;s.end()}}
#[derive(Serialize)]enum BorrowedReply<'a>{GenerationFragment{sequence:u32,offset:u64,bytes:&'a[u8]}}
struct Encoder<'a>{file:&'a mut File,total:u64,hash:xxhash_rust::xxh3::Xxh3}
impl Write for Encoder<'_>{fn write(&mut self,bytes:&[u8])->io::Result<usize>{let next=self.total.checked_add(bytes.len()as u64).filter(|n|*n<=OUTPUT).ok_or_else(||io::Error::new(io::ErrorKind::OutOfMemory,"generation metadata reply exceeds existing 64MiB envelope"))?;self.file.write_all(bytes)?;self.hash.update(bytes);self.total=next;Ok(bytes.len())}fn flush(&mut self)->io::Result<()>{self.file.flush()}}
pub(super) enum Executed{Build(crate::request::BuildOutcome),Generated(Report),Derived(bool,super::analyze::FundedBytes)}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub(crate) struct GenerationAbort{pub failure:crate::request_failure::RequestFailure,pub os_code:Option<i32>,pub committed:bool,pub may_have_changed:bool,pub details_complete:bool}
pub(super) fn committed(error:&(dyn Error+'static))->bool{error.downcast_ref::<crate::generation_coordinator::CoordinatorFailure>().is_some_and(|value|value.committed)}
pub(super) fn may_have_changed(error:&(dyn Error+'static))->bool{let primary=error.downcast_ref::<crate::generation_coordinator::CoordinatorFailure>().map_or(error,|value|value.primary.as_ref());committed(error)||primary.downcast_ref::<crate::generation_transaction::TransactionError>().is_some_and(|value|!value.rollback.is_empty())}
struct SmallDisplay{value:String,truncated:bool}
impl fmt::Write for SmallDisplay{fn write_str(&mut self,text:&str)->fmt::Result{let mut count=text.len().min(4096usize.saturating_sub(self.value.len()));while !text.is_char_boundary(count){count-=1}self.value.push_str(&text[..count]);self.truncated|=count<text.len();Ok(())}}
pub(super) fn send_abort(stream:&mut impl Write,error:&(dyn Error+'static),committed:bool,may_have_changed:bool)->io::Result<()>{let mut text=SmallDisplay{value:String::new(),truncated:false};text.value.try_reserve_exact(4160).map_err(|cause|io::Error::new(io::ErrorKind::OutOfMemory,cause))?;if text.value.capacity()>4*4160{return Err(io::ErrorKind::OutOfMemory.into())}fmt::write(&mut text,format_args!("{error}")).map_err(io::Error::other)?;if text.truncated{text.value.push_str(" [details truncated]")}let failure=crate::request_failure::RequestFailure{kind:crate::request_failure::classify(error),message:text.value};super::protocol::send(stream,&super::protocol::Reply::GenerationAborted(GenerationAbort{failure,os_code:actual_io(error).and_then(io::Error::raw_os_error),committed,may_have_changed,details_complete:false}))}
pub(super) fn send_report(stream:&mut impl Write,report:&Report,cache:&Path)->io::Result<()>{let clean=report.rows.len()>0&&report.diagnostics.is_empty()&&report.cleanup.is_empty()&&report.rows.iter().all(|row|matches!(row.state,State::Fresh|State::Written));send_value(stream,&ReportWire(report,clean),cache,Status::Completed,clean,report.committed,report.committed,report.cleanup.len())}
pub(super) fn send_error(stream:&mut impl Write,error:&(dyn Error+'static),cache:&Path)->io::Result<()>{let mut primary=error;let mut cleanup=&[][..];let mut pending_cleanup=&[][..];let mut committed=false;if let Some(value)=error.downcast_ref::<crate::generation_coordinator::CoordinatorFailure>(){primary=value.primary.as_ref();cleanup=&value.cleanup;pending_cleanup=&value.pending_cleanup;committed=value.committed;}let rollback=if let Some(value)=primary.downcast_ref::<crate::generation_transaction::TransactionError>(){primary=value.primary.as_ref();&value.rollback[..]}else{&[][..]};send_value(stream,&FailureWire{primary,rollback,cleanup,pending_cleanup,committed},cache,Status::Failed,false,committed,committed||!rollback.is_empty(),cleanup.len().checked_add(pending_cleanup.len()).ok_or(io::ErrorKind::OutOfMemory)?)}
fn send_value(stream:&mut impl Write,value:&impl Serialize,cache:&Path,status:Status,clean:bool,committed:bool,may_have_changed:bool,warnings:usize)->io::Result<()>{let mut file=crate::generation_staging::temporary_output(cache)?;let mut encoder=Encoder{file:&mut file,total:0,hash:xxhash_rust::xxh3::Xxh3::new()};serde_json::to_writer(&mut encoder,value).map_err(io::Error::other)?;encoder.flush()?;let total=encoder.total;let hash=encoder.hash.digest128();drop(encoder);file.seek(SeekFrom::Start(0))?;let mut bytes=Vec::new();bytes.try_reserve_exact(FRAGMENT).map_err(|error|io::Error::new(io::ErrorKind::OutOfMemory,error))?;if bytes.capacity()>4*FRAGMENT{return Err(io::ErrorKind::OutOfMemory.into())}bytes.resize(FRAGMENT,0);let mut offset=0;let mut sequence=0;while offset<total{super::control::checkpoint()?;let size=usize::try_from((total-offset).min(FRAGMENT as u64)).unwrap();file.read_exact(&mut bytes[..size])?;super::protocol::send(stream,&BorrowedReply::GenerationFragment{sequence,offset,bytes:&bytes[..size]})?;offset+=size as u64;sequence+=1;}super::control::checkpoint()?;super::protocol::send(stream,&super::protocol::Reply::GenerationFinished(GenerationTerminal{status,clean,fragments:sequence,total,hash,committed,may_have_changed,cleanup_warnings:u32::try_from(warnings).map_err(|_|io::Error::other("generation warning count overflow"))?}))}

#[path="generation_client.rs"]mod client;
pub use client::run_file;

#[cfg(test)]pub(crate) fn consume_for_test(stream:&mut super::transport::Stream,request:&GenerationRequest,output:&mut impl Write)->Result<bool,Box<dyn Error>>{client::receive_test(stream,request,output)}

#[cfg(test)]mod tests{use super::*;#[test]fn generation_abort_frame_preserves_actual_io_and_committed_uncertainty(){let mut wire=Vec::new();send_abort(&mut wire,&io::Error::from_raw_os_error(1450),true,true).unwrap();let super::super::protocol::Reply::GenerationAborted(abort)=super::super::protocol::receive(&mut wire.as_slice()).unwrap()else{panic!("typed abort")};assert_eq!(abort.os_code,Some(1450));assert!(abort.committed&&abort.may_have_changed);assert!(!abort.details_complete);}#[test]fn generation_request_uses_only_actual_workspace_intent_and_refuses_other_roles(){let(_,mut build,_,_)=crate::generation_test_fixture::fixture();build.policy_inputs.as_mut().unwrap().workspace_generators=vec![crate::GeneratorName::Deps];let mut request=GenerationRequest{build,check:true};request.validate().unwrap();super::super::build_admission::validate(&request.build).unwrap();validate_cache(&request.build).unwrap();request.build.command=BuildCommand::Compile;assert!(request.validate().is_err());request.build.command=BuildCommand::PrepareQuery;request.build.policy_inputs.as_mut().unwrap().workspace_generators=vec![crate::GeneratorName::Deps,crate::GeneratorName::Deps];assert!(super::super::build_admission::validate(&request.build).is_err());}}
